// Embeds the FOGRA39 colour profile into the server bundle as base64.
//
// The flyer print tool's /admin/tools/flyer-print/fogra39 route used to read
// this file from disk, but Cloudflare Workers have no filesystem. It can't go
// in public/ either: it must only be handed to signed-in staff (see
// lib/flyer-print/profiles/NOTICE.txt). So it's compiled into the Worker.
//
// Output is build output (git-ignored), regenerated by the predev / prebuild
// hooks in package.json.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const dir = join(dirname(fileURLToPath(import.meta.url)), "..", "lib", "flyer-print", "profiles");
const bytes = readFileSync(join(dir, "ISOcoated_v2_eci.icc"));
writeFileSync(
  join(dir, "fogra39.generated.ts"),
  `// Generated by scripts/embed-icc-profile.mjs — do not edit.\nimport "server-only";\n\nexport const FOGRA39_ICC_BASE64 =\n  "${bytes.toString("base64")}";\n`,
);
console.log(`embed-icc-profile: embedded ${bytes.length} bytes`);
